function setupMobileSiteHeader(){
  if(document.body.classList.contains('admin-body')) return;
  document.querySelectorAll('header.topbar').forEach(header=>{
    const brand=header.querySelector('.brand');
    if(!brand) return;
    brand.classList.add('site-brand');
    brand.setAttribute('aria-label','LuMekH home');
    const oldLogo=brand.querySelector('img');
    const mark=brand.querySelector('.brand-mark');
    if(mark) mark.remove();
    if(!oldLogo){
      const logo=document.createElement('img');
      logo.className='header-site-logo';
      logo.src='/assets/lumekh-logo.png?v=brand-20261113';
      logo.alt='';
      brand.prepend(logo);
    }else oldLogo.classList.add('header-site-logo');
    if(!brand.querySelector('.brand-copy,.home-brand-type')){
      const copy=document.createElement('span');
      copy.className='brand-copy';
      copy.innerHTML='<strong>LuMekH™</strong><small>Love We Make</small>';
      brand.append(copy);
    }else if(!brand.querySelector('.brand-copy') && brand.querySelector('.home-brand-type')){
      brand.querySelector('.home-brand-type').classList.add('brand-copy');
    }
    let nav=header.querySelector('nav');
    if(!nav){nav=document.createElement('nav');header.append(nav)}
    nav.classList.add('site-menu');
    nav.setAttribute('aria-label','Main navigation');
    const links=[
      ['Menu','/#services','menu-home'],
      ['Services','/Services','menu-services'],
      ['Store','/Store','menu-store'],
      ['My Account','/My-Account','menu-account']
    ];
    links.forEach(([label,href,key])=>{
      let existing=nav.querySelector('[data-site-nav="'+key+'"]');
      if(!existing) existing=[...nav.querySelectorAll('a.navlink')].find(a=>a.textContent.trim().toLowerCase()===label.toLowerCase()||a.getAttribute('href')===href);
      if(existing){existing.dataset.siteNav=key}
      else{
        const a=document.createElement('a');
        a.className='navlink';a.href=href;a.dataset.siteNav=key;a.textContent=label;
        nav.insertBefore(a,nav.querySelector('.header-cart')||null);
      }
    });
    let cart=nav.querySelector('.header-cart');
    if(!cart){
      cart=document.createElement('a');
      cart.className='header-cart';cart.href='/Store#basket';cart.setAttribute('aria-label','Shopping cart');
      cart.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 8h14l-1 12H6L5 8Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/></svg><span class="cart-badge" id="header-cart-count">0</span>';
      nav.append(cart);
    }
    let toggle=nav.querySelector('.mobile-menu-toggle');
    if(!toggle){
      toggle=document.createElement('button');
      toggle.type='button';toggle.className='mobile-menu-toggle';
      toggle.setAttribute('aria-label','Open menu');toggle.setAttribute('aria-expanded','false');
      toggle.setAttribute('aria-controls','mobile-site-menu');
      toggle.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h16"/></svg>';
      nav.append(toggle);
    }
    let panel=nav.querySelector('.mobile-menu-panel');
    if(!panel){
      panel=document.createElement('div');
      panel.className='mobile-menu-panel';panel.id='mobile-site-menu';panel.hidden=true;
      [['Home','/Home'],['Services','/Services'],['Products','/Store'],['My Account','/My-Account']].forEach(([label,href])=>{const a=document.createElement('a');a.href=href;a.textContent=label;panel.append(a)});
      nav.append(panel);
    }
    if(!toggle.dataset.ready){
      toggle.dataset.ready='true';
      toggle.addEventListener('click',()=>{
        const open=toggle.getAttribute('aria-expanded')!=='true';
        toggle.setAttribute('aria-expanded',String(open));
        toggle.setAttribute('aria-label',open?'Close menu':'Open menu');
        panel.hidden=!open;
      });
      document.addEventListener('click',event=>{
        if(!nav.contains(event.target)){toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open menu');panel.hidden=true}
      });
      document.addEventListener('keydown',event=>{
        if(event.key==='Escape'){toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open menu');panel.hidden=true}
      });
      panel.addEventListener('click',event=>{if(event.target.closest('a')){toggle.setAttribute('aria-expanded','false');panel.hidden=true}});
    }
  });
}
